function sampleVanillaFoliageColor(u, v) {
  const x = textureCoordinate(u);
  const y = textureCoordinate(v);
  const offset2 = (y * WIDTH + x) * 4;
  const first = decodeBase64Character(ENCODED_RGB.charCodeAt(offset2));
  const second = decodeBase64Character(ENCODED_RGB.charCodeAt(offset2 + 1));
  const third = decodeBase64Character(ENCODED_RGB.charCodeAt(offset2 + 2));
  const fourth = decodeBase64Character(ENCODED_RGB.charCodeAt(offset2 + 3));
  return {
    red: (first << 2 | second >> 4) / 255,
    green: ((second & 15) << 4 | third >> 2) / 255,
    blue: ((third & 3) << 6 | fourth) / 255
  };
}
function textureCoordinate(value) {
  const clamped = Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
  return Math.floor(clamped * (WIDTH - 1));
}
function decodeBase64Character(code) {
  if (code >= 65 && code <= 90) return code - 65;
  if (code >= 97 && code <= 122) return code - 71;
  if (code >= 48 && code <= 57) return code + 4;
  if (code === 43) return 62;
  if (code === 47) return 63;
  return 0;
}

