var DEFAULT_BLOCK_BREAK_SOUND = "dig.wood";
var DEFAULT_LEAF_BREAK_SOUND = "dig.grass";
function resolveVanillaBlockBreakSound(typeId) {
  if (!typeId) return DEFAULT_BLOCK_BREAK_SOUND;
  const normalized = typeId.includes(":") ? typeId : `minecraft:${typeId}`;
  return VANILLA_BLOCK_BREAK_SOUNDS[normalized] ?? (isPhysicsLeaf(normalized) ? DEFAULT_LEAF_BREAK_SOUND : DEFAULT_BLOCK_BREAK_SOUND);
}
function selectDominantVanillaBlockBreakSound(typeIds) {
  if (typeIds.length === 0) return DEFAULT_BLOCK_BREAK_SOUND;
  const counts = /* @__PURE__ */ new Map();
  let selected = DEFAULT_BLOCK_BREAK_SOUND;
  let selectedCount = 0;
  for (const typeId of typeIds) {
    const sound = resolveVanillaBlockBreakSound(typeId);
    const count = (counts.get(sound) ?? 0) + 1;
    counts.set(sound, count);
    if (count > selectedCount) {
      selected = sound;
      selectedCount = count;
    }
  }
  return selected;
}

// src/PhysicsPhysics/physics/rotation-continuity.ts
var DEGREES_TO_RADIANS = Math.PI / 180;
var RADIANS_TO_DEGREES = 180 / Math.PI;
function rotateVectorByEulerDegreesYzx(vector, rotation) {
  const halfX = rotation.x * DEGREES_TO_RADIANS / 2;
  const halfY = rotation.y * DEGREES_TO_RADIANS / 2;
  const halfZ = rotation.z * DEGREES_TO_RADIANS / 2;
  const c1 = Math.cos(halfX);
  const c2 = Math.cos(halfY);
  const c3 = Math.cos(halfZ);
  const s1 = Math.sin(halfX);
  const s2 = Math.sin(halfY);
  const s3 = Math.sin(halfZ);
  const qx = s1 * c2 * c3 + c1 * s2 * s3;
  const qy = c1 * s2 * c3 + s1 * c2 * s3;
  const qz = c1 * c2 * s3 - s1 * s2 * c3;
  const qw = c1 * c2 * c3 - s1 * s2 * s3;
  const ix = qw * vector.x + qy * vector.z - qz * vector.y;
  const iy = qw * vector.y + qz * vector.x - qx * vector.z;
  const iz = qw * vector.z + qx * vector.y - qy * vector.x;
  const iw = -qx * vector.x - qy * vector.y - qz * vector.z;
  return {
    x: ix * qw - iw * qx - iy * qz + iz * qy,
    y: iy * qw - iw * qy - iz * qx + ix * qz,
    z: iz * qw - iw * qz - ix * qy + iy * qx
  };
}

