    speed = new ObservableNumber(Math.max(0, Math.min(32, Number(propeller.snapshot.propellerSpeed ?? 0))), { clientWritable: true });
    steering = new ObservableBoolean(propeller.snapshot.propellerSteeringControlled === true, { clientWritable: true });
