      const nextSpeed = Math.max(0, Math.min(32, Math.round(speed.getData())));
      propeller.snapshot.propellerEnabled = nextEnabled;
      propeller.snapshot.propellerSpeed = nextSpeed;
      propeller.snapshot.propellerReverse = false;
