      // Drive through the center of mass to translate without adding torque.
      const forcePoint = body.localPointToWorld(body.getCenterOfMass());
      body.applyForceAt(forcePoint, {
        x: direction.x * force,
        y: direction.y * force,
        z: direction.z * force
      });
