function syncHandrailControllerSession(session) {
  const entry = session.handrailEntry;
  const cargo = entry?.state.cargo;
  if (!cargo || !entry.entity.isValid || !session.assembly?.isValid) return false;
  try {
  const previous = new Map(cargo.blocks.map(b => [`${b.dx},${b.dy},${b.dz}`, b]));
  cargo.blocks = session.snapshots.map(snapshot => {
    const dx = snapshot.location.x-session.location.x;
    const dy = snapshot.location.y-session.location.y;
    const dz = snapshot.location.z-session.location.z;
    const old = previous.get(`${dx},${dy},${dz}`);
    previous.delete(`${dx},${dy},${dz}`);
    const {permutation,location,...data} = snapshot;
    return {...old,...data,dx,dy,dz,states:permutation.getAllStates()};
  });
  cargo.visualIds = session.assembly.visualEntityIds;
  entry.entity.setDynamicProperty("create_physics:handrail_motion", JSON.stringify(entry.state));
  // The native mining path already dropped/removed these blocks and inventories.
  for (const removed of previous.values()) if (removed.structure) world8.structureManager.delete(removed.structure);
  return true;
  } catch { return false; }
}

function configureHandrailControllerEntities(session) {
  reconnectPhysicsStorageEntities(session);
  ensureEmptyPhysicsChestInventories(session, session.snapshots.filter(s=>!s.storageEntityId));
  ensurePhysicsVaultInventories(session);
  schedulePhysicsFenceEntityConfiguration(session);
  configurePhysicsPropellerEntities(session);
  createPhysicsHandleInteractionEntities(session);
  createPhysicsPropellerInteractionEntities(session);
  createHotAirBurnerInteractionEntities(session);
  createPhysicsArmchairSeats(session);
  createPhysicsControllerCreateCollisionEntities(session);
}

function handrailAssemblyOptions(axis) {
  return {
    motionType: "dynamic", allowSleep: false,
    baseBlocks: [{ typeId: "create_physics:handrail_panel", itemTypeId: "create_physics:handrail_panel", render: false,
      localLocation: { x: 0, y: 0, z: 0 }, mass: 2, collisionResponse: false,
      collisionShape: [{ min: { x: 0, y: 0.75, z: 0 }, max: { x: 1, y: 1, z: 1 } }] }],
    linearFactor: { x: axis === "x" ? 1 : 0, y: 0, z: axis === "z" ? 1 : 0 },
    angularFactor: { x: 0, y: 0, z: 0 }
  };
}

